import React from 'react';
import styled from 'styled-components';


const Info = () => {
    return (
        <InfoBox>
            <InfoTitle>Kompleksowa obsługa Twojego przedsiębiorstwa</InfoTitle>
            <InfoSubtitle>
                Jednoosobowa działalność gospodarcza czy może spółka cywilna?
                Z ponad dwudziestoletnim doświadczeniem
                potrafimy odpowiedzieć na potrzeby każdej firmy - niezależnie od jej złożoności, specyfiki czy też reprezentowanej branży.
                Świadczone przez nas usługi są zawsze dostosowywane indywidualnie z zachowaniem najwyższych standardów obsługi klienta. Służymy także pomocą osobom chcącym dopiero rozpocząć swoją działalność gospodarczą oraz firmom stawiającym pierwsze kroki na rynku.
            </InfoSubtitle>
        </InfoBox>
    );
}

export default Info

const InfoBox = styled.div`
    width: 100%;
    padding-top: 6.5rem;
    padding-bottom: 6.5rem;
`;

const InfoTitle = styled.h1`
    text-align: center;
`;

const InfoSubtitle = styled.p`
    margin: 48px;
    margin-left: 30px;
    margin-right: 30px;
    text-align: center;
    line-height: 1.666;
`;

//ż
